<div class="page-head"><div><h1>Mis facturas</h1><p>Comprobantes emitidos a tu empresa y su estado de pago.</p></div></div>
<div class="card-ui"><div class="table-responsive"><table class="table-ui"><thead><tr><th>Comprobante</th><th>Emisión</th><th>Vence</th><th class="text-end">Total</th><th class="text-end">Saldo</th><th>Estado</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $f): ?><tr><td><b><?= e($f['codigo']) ?></b></td><td class="small"><?= fdate($f['fecha_emision']) ?></td><td class="small <?= $f['vencida'] ? 'text-danger fw-semibold' : '' ?>"><?= fdate($f['fecha_vencimiento']) ?></td><td class="text-end fw-semibold"><?= money($f['total']) ?></td><td class="text-end"><?= $f['estado'] === 'emitida' ? money($f['saldo']) : '—' ?></td>
  <td><?= $f['estado'] === 'pagada' ? pill('Pagada', 'success') : ($f['vencida'] ? pill('Vencida', 'danger') : ($f['pagado'] > 0 ? pill('Pago parcial', 'soft-warning') : pill('Pendiente', 'soft-info'))) ?></td><td class="text-end"><a target="_blank" href="<?= url('portal/comprobante/' . $f['id']) ?>" class="btn btn-soft btn-sm"><i class="bi bi-printer"></i> Ver</a></td></tr>
